const $=id=>document.getElementById(id),canvas=$('map'),ctx=canvas.getContext('2d');let data,selected=0,points=[],visible=[],visibleSet=new Set(),camera={x:0,y:0,k:1},bounds={},worker,page=0,search='',w=800,h=455,drag=null,lastTap=null,pinch=null;
const color=s=>data.depth[s]===0?'#ec6a4b':data.depth[s]===1?'#e9ae40':'#6366e7';
const edgeArray=s=>data.pairs.filter((_,i)=>s&(1<<i));
