const pop=s=>{let c=0;for(;s;s&=s-1)c++;return c};
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3200)}
function run(){const n=Number($('n').value);if(worker)worker.terminate();$('loading').classList.remove('hidden');$('run').disabled=true;worker=new Worker('worker.js');worker.onmessage=e=>{if(e.data.error){toast(e.data.error);$('run').disabled=false;$('loading').classList.add('hidden');return}data=e.data.data;selected=0;page=0;search='';$('search').value='';$('search').max=data.count-1;$('states').textContent=data.count.toLocaleString();$('cycles').textContent=data.cycles.length.toLocaleString();$('periods').textContent=[...new Set(data.cycles.map(c=>c.length))].sort((a,b)=>a-b).join(', ');$('maxdepth').textContent=data.maxDepth;$('basin').innerHTML='<option value="all">All basins</option>'+data.cycles.map((c,i)=>`<option value="${i}">B${i+1} · ${data.sizes[i]} states · period ${c.length}</option>`).join('');$('run').disabled=false;$('loading').classList.add('hidden');layout();inspect(0);renderRows()};worker.onerror=()=>{toast('Could not start the analysis worker. Reload the page to retry.');$('run').disabled=false;$('loading').classList.add('hidden')};worker.postMessage(n)}
function layout(){if(!data)return;const choice=$('basin').value,bs=choice==='all'?data.cycles.map((_,i)=>i):[Number(choice)];visible=[];points=new Array(data.count);const grouped=new Map(bs.map(b=>[b,new Map()]));for(let s=0;s<data.count;s++){const layers=grouped.get(data.basin[s]);if(!layers)continue;const d=data.depth[s];if(!layers.has(d))layers.set(d,[]);layers.get(d).push(s);visible.push(s)}const tiles=bs.map(b=>{const layers=grouped.get(b);return{b,layers,width:Math.max(...[...layers.values()].map(a=>a.length))*52+60,depth:Math.max(...layers.keys())}});const area=tiles.reduce((a,t)=>a+(t.width+60)*(t.depth*115+160),0),target=Math.max(Math.sqrt(area*w/h),...tiles.map(t=>t.width));let left=0,top=0,rowHeight=0;for(const tile of tiles){if(left&&left+tile.width>target){left=0;top+=rowHeight+65;rowHeight=0}for(const [d,states]of tile.layers){states.sort((a,b)=>data.next[a]-data.next[b]||a-b);states.forEach((s,i)=>points[s]={x:left+tile.width/2+(i-(states.length-1)/2)*52,y:top+(tile.depth-d)*115+50})}left+=tile.width+60;rowHeight=Math.max(rowHeight,tile.depth*115+110)}const xs=visible.map(s=>points[s].x),ys=visible.map(s=>points[s].y);bounds={minX:Math.min(...xs)-40,maxX:Math.max(...xs)+40,minY:Math.min(...ys)-50,maxY:Math.max(...ys)+50};$('scope').textContent=`${visible.length.toLocaleString()} states · ${bs.length.toLocaleString()} ${bs.length===1?'basin':'basins'} · arrows show one progression step`;$('fit').textContent=choice==='all'?'Fit all':'Fit basin';fit()}

function fit(){camera.k=Math.min((w-65)/(bounds.maxX-bounds.minX),(h-80)/(bounds.maxY-bounds.minY),2);camera.x=w/2-(bounds.minX+bounds.maxX)/2*camera.k;camera.y=h/2-(bounds.minY+bounds.maxY)/2*camera.k;draw()}
function zoom(f,x=w/2,y=h/2){const old=camera.k;camera.k=Math.max(.00002,Math.min(6,old*f));camera.x=x-(x-camera.x)*camera.k/old;camera.y=y-(y-camera.y)*camera.k/old;draw()}
function pathFor(s){const list=[],seen=new Map();let t=s;while(!seen.has(t)){seen.set(t,list.length);list.push(t);t=data.next[t]}return{list:[...list,t],start:seen.get(t)}}
function draw(){ctx.clearRect(0,0,w,h);if(!data)return;$('scale').textContent=`${Math.round(camera.k*1000)/10}%`;const k=camera.k,screen=p=>({x:p.x*k+camera.x,y:p.y*k+camera.y});const path=new Set(pathFor(selected).list);const on=p=>p.x>-40&&p.x<w+40&&p.y>-40&&p.y<h+40;
function edge(s,active){const t=data.next[s],a=screen(points[s]),b=screen(points[t]);if(!on(a)&&!on(b)&&((a.x<0&&b.x<0)||(a.x>w&&b.x>w)||(a.y<0&&b.y<0)||(a.y>h&&b.y>h)))return;ctx.strokeStyle=active?'#5851d9':data.depth[s]===0?'#ec6a4b':'#c9cbdc';ctx.globalAlpha=active?1:k<.08?.15:.6;ctx.lineWidth=active?2:1;ctx.beginPath();let tx,ty,ang;if(s===t){const r=Math.max(7,14*k);ctx.arc(a.x,a.y-r,r,.25,Math.PI*2+.25);tx=a.x+r;ty=a.y-r;ang=Math.PI/2}else if(data.depth[s]===0){const mx=(a.x+b.x)/2,my=(a.y+b.y)/2,dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,cx=mx-dy/len*25*k,cy=my+dx/len*25*k;ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(cx,cy,b.x,b.y);const v=.67;tx=(1-v)**2*a.x+2*(1-v)*v*cx+v*v*b.x;ty=(1-v)**2*a.y+2*(1-v)*v*cy+v*v*b.y;ang=Math.atan2((1-v)*(cy-a.y)+v*(b.y-cy),(1-v)*(cx-a.x)+v*(b.x-cx))}else{ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);tx=a.x+.7*(b.x-a.x);ty=a.y+.7*(b.y-a.y);ang=Math.atan2(b.y-a.y,b.x-a.x)}ctx.stroke();if(k>.15||active){ctx.beginPath();ctx.moveTo(tx,ty);ctx.lineTo(tx-5*Math.cos(ang-.45),ty-5*Math.sin(ang-.45));ctx.moveTo(tx,ty);ctx.lineTo(tx-5*Math.cos(ang+.45),ty-5*Math.sin(ang+.45));ctx.stroke()}}
visible.forEach(s=>edge(s,false));visible.filter(s=>path.has(s)).forEach(s=>edge(s,true));ctx.globalAlpha=1;for(const s of visible){const p=screen(points[s]);if(!on(p))continue;const r=Math.max(1.1,Math.min(9,7*k));ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=color(s);ctx.fill();if(s===selected){ctx.strokeStyle='#292357';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,r+4,0,Math.PI*2);ctx.stroke()}if(k>.55){ctx.font=`${Math.min(12,10*k)}px system-ui`;ctx.textAlign='center';ctx.fillStyle='#777d91';ctx.fillText(`G${s}`,p.x,p.y+Math.max(14,18*k))}}}
function inspect(s){selected=s;const d=new Array(data.n).fill(0),edges=edgeArray(s);edges.forEach(([u,v])=>{d[u]++;d[v]++});$('state-tag').textContent=`G${s}`;$('badges').innerHTML=`<span class="badge">${data.depth[s]===0?'Attractor':`${data.depth[s]} steps to cycle`}</span><span class="badge">Period ${data.cycles[data.basin[s]].length}</span><span class="badge">Basin B${data.basin[s]+1}</span>`;$('edges').textContent=edgeText(s);$('degrees').innerHTML=d.map((v,i)=>`<span>${i}: <b>${v}</b></span>`).join('');const coords=d.map((_,i)=>({x:140+66*Math.cos(i*2*Math.PI/data.n-Math.PI/2),y:88+66*Math.sin(i*2*Math.PI/data.n-Math.PI/2)}));$('preview').innerHTML=edges.map(([u,v])=>`<line x1="${coords[u].x}" y1="${coords[u].y}" x2="${coords[v].x}" y2="${coords[v].y}" stroke="#aaa7d9" stroke-width="2"/>`).join('')+coords.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="12" fill="#f0effb" stroke="#7c75dc"/><text x="${p.x}" y="${p.y+4}" text-anchor="middle" font-size="11" fill="#4b459c">${i}</text>`).join('');draw()}
function centerState(){if(!visibleSet.has(selected)){$('basin').value=String(data.basin[selected]);layout()}camera.k=1.5;camera.x=w/2-points[selected].x*camera.k;camera.y=h/2-points[selected].y*camera.k;draw()}
function filtered(){if(!data)return[];return visible.filter(s=>search===''||s===Number(search)).sort((a,b)=>a-b)}
function renderRows(){const ids=filtered(),total=Math.max(1,Math.ceil(ids.length/12));page=Math.max(0,Math.min(page,total-1));$('page').textContent=`${page+1} / ${total}`;$('prev').disabled=page===0;$('next').disabled=page>=total-1;$('result-count').textContent=`${ids.length.toLocaleString()} starting states`;$('trajectory-list').innerHTML=ids.slice(page*12,page*12+12).map(s=>`<details class="trajectory-row" data-state="${s}"><summary><span class="row-id">G${s}</span><span class="row-edges">${edgeText(s)}</span><span class="row-meta">${data.depth[s]} transient · period ${data.cycles[data.basin[s]].length}</span><span>＋</span></summary><div class="path"></div></details>`).join('')||(search!==''?'<p style="padding:20px">No matching state in this basin.</p>':'');document.querySelectorAll('.trajectory-row').forEach(el=>el.addEventListener('toggle',()=>{if(!el.open||el.dataset.filled)return;el.dataset.filled='yes';const {list,start}=pathFor(Number(el.dataset.state));el.querySelector('.path').innerHTML=list.map((s,i)=>`${i?'<span class="arrow">→</span>':''}<button data-pick="${s}" class="${i>=start?'cycle':''} ${i===list.length-1?'repeat':''}">G${s}<small>Step ${i} · ${i===list.length-1?'first repeat':i>=start?'cycle':'transient'}</small></button>`).join('')}))}
$('trajectory-list').onclick=e=>{const b=e.target.closest('[data-pick]');if(b){inspect(Number(b.dataset.pick));centerState()}};
$('n').onchange=()=>{const n=Number($('n').value),m=n*(n-1)/2;$('estimate').textContent=`${m} possible edges · ${(2**m).toLocaleString()} labeled graph states${n===6?' · use basin filters for detail':''}`};$('run').onclick=run;$('basin').onchange=()=>{page=0;layout();renderRows()};$('in').onclick=()=>zoom(1.5);$('out').onclick=()=>zoom(1/1.5);$('fit').onclick=fit;$('center').onclick=centerState;$('trace').onclick=()=>{$('search').value=selected;search=String(selected);page=0;if(!visibleSet.has(selected)){$('basin').value='all';layout()}renderRows();const el=document.querySelector('.trajectory-row');if(el)el.open=true;$('trajectory-section').scrollIntoView({behavior:'smooth'})};$('search').oninput=()=>{search=$('search').value;page=0;renderRows()};$('prev').onclick=()=>{page--;renderRows()};$('next').onclick=()=>{page++;renderRows()};$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.map-panel').requestFullscreen()}catch{toast('Fullscreen is unavailable in this browser.')}};
canvas.onwheel=e=>{e.preventDefault();const r=canvas.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top)};
const pointers=new Map();canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});drag={x:e.clientX,y:e.clientY,ox:camera.x,oy:camera.y,moved:false};lastTap={x:e.clientX,y:e.clientY};if(pointers.size===2){const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y)}};
canvas.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y),r=canvas.getBoundingClientRect();if(pinch)zoom(dist/pinch,(a.x+b.x)/2-r.left,(a.y+b.y)/2-r.top);pinch=dist;drag=null;lastTap=null;return}if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;camera.x=drag.ox+dx;camera.y=drag.oy+dy;draw()};
canvas.onpointerup=e=>{pointers.delete(e.pointerId);if(drag&&!drag.moved&&lastTap){const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let best=null,dist=18;for(const s of visible){const p=points[s],d=Math.hypot(x-(p.x*camera.k+camera.x),y-(p.y*camera.k+camera.y));if(d<dist){dist=d;best=s}}if(best!==null)inspect(best)}drag=null;lastTap=null;pinch=null};canvas.onpointercancel=()=>{pointers.clear();drag=null;pinch=null};canvas.onkeydown=e=>{if(e.key==='+'||e.key==='=')zoom(1.4);else if(e.key==='-')zoom(1/1.4);else if(e.key==='0')fit();else if(e.key.startsWith('Arrow')){e.preventDefault();camera.x+=e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0;camera.y+=e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0;draw()}};
new ResizeObserver(()=>{const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const ratio=devicePixelRatio||1;canvas.width=w*ratio;canvas.height=h*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);draw()}).observe($('wrap'));
function saveBlob(content,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export').onclick=()=>{if(!data)return;saveBlob(JSON.stringify({n:data.n,edgeBitOrder:data.pairs,cycles:data.cycles,states:Array.from({length:data.count},(_,s)=>({id:s,edges:edgeArray(s),next:data.next[s],basin:data.basin[s]+1,transientSteps:data.depth[s],period:data.cycles[data.basin[s]].length}))},null,2),`graph-analysis-n${data.n}.json`,'application/json')};
$('download').onclick=()=>{const a=document.createElement('a');a.href='graph-progression-lab.zip';a.download='graph-progression-lab.zip';a.click()};run();
